/**
 * Media uploads. Files are type-checked by their bytes (not the client's claim)
 * and scrubbed of anything that could give the answer away:
 * - images are cropped to one standard 4:3 frame and size (AI images often have
 *   tell-tale square or generator-native sizes) and re-encoded without metadata;
 * - audio and video are remuxed by ffmpeg with all metadata removed (encoder tags,
 *   "generated by" comments, content-credential boxes).
 * Results are stored locally (UPLOAD_DIR) or in an S3-compatible bucket (S3_BUCKET).
 */
import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { promisify } from "node:util";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import sharp from "sharp";
import type { MediaType } from "@/lib/contracts";
import { HttpError } from "./http";

type Kind = { mediaType: MediaType; ext: string; mime: string; maxBytes: number };

const MB = 1024 * 1024;
const IMAGE: Kind = { mediaType: "image", ext: "jpg", mime: "image/jpeg", maxBytes: 8 * MB };

export const MIME_BY_EXT: Record<string, string> = {
  jpg: "image/jpeg",
  mp3: "audio/mpeg",
  m4a: "audio/mp4",
  ogg: "audio/ogg",
  wav: "audio/wav",
  mp4: "video/mp4",
  webm: "video/webm",
};

const ascii = (buf: Buffer, start: number, end: number) => buf.subarray(start, end).toString("latin1");

/** Identifies a file from its magic bytes. */
export function sniff(buf: Buffer): Kind | null {
  if (buf.length < 12) return null;
  if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return IMAGE; // JPEG
  if (ascii(buf, 1, 4) === "PNG") return IMAGE;
  if (ascii(buf, 0, 4) === "RIFF" && ascii(buf, 8, 12) === "WEBP") return IMAGE;
  if (ascii(buf, 0, 4) === "RIFF" && ascii(buf, 8, 12) === "WAVE") return { mediaType: "audio", ext: "wav", mime: MIME_BY_EXT.wav, maxBytes: 15 * MB };
  if (ascii(buf, 0, 3) === "ID3" || (buf[0] === 0xff && (buf[1] & 0xe0) === 0xe0))
    return { mediaType: "audio", ext: "mp3", mime: MIME_BY_EXT.mp3, maxBytes: 15 * MB };
  if (ascii(buf, 0, 4) === "OggS") return { mediaType: "audio", ext: "ogg", mime: MIME_BY_EXT.ogg, maxBytes: 15 * MB };
  if (ascii(buf, 4, 8) === "ftyp") {
    const brand = ascii(buf, 8, 12);
    return brand.startsWith("M4A")
      ? { mediaType: "audio", ext: "m4a", mime: MIME_BY_EXT.m4a, maxBytes: 15 * MB }
      : { mediaType: "video", ext: "mp4", mime: MIME_BY_EXT.mp4, maxBytes: 40 * MB };
  }
  if (buf[0] === 0x1a && buf[1] === 0x45 && buf[2] === 0xdf && buf[3] === 0xa3)
    return { mediaType: "video", ext: "webm", mime: MIME_BY_EXT.webm, maxBytes: 40 * MB };
  return null;
}

export const MAX_UPLOAD_BYTES = 40 * MB;

/** Every uploaded image becomes exactly this size, so shape and size never hint at the answer. */
export const IMAGE_WIDTH = 1600;
export const IMAGE_HEIGHT = 1200;

const run = promisify(execFile);

/** Re-muxes audio/video without any metadata. Throws if ffmpeg is unavailable. */
async function stripAvMetadata(input: Buffer, ext: string): Promise<Buffer> {
  const dir = await mkdtemp(path.join(os.tmpdir(), "rr-av-"));
  const src = path.join(dir, `in.${ext}`);
  const out = path.join(dir, `out.${ext}`);
  try {
    await writeFile(src, input);
    const args = ["-hide_banner", "-loglevel", "error", "-y", "-i", src, "-map", "0:a?", "-map", "0:v?"];
    args.push("-map_metadata", "-1", "-map_chapters", "-1", "-c", "copy", "-fflags", "+bitexact");
    if (ext === "mp4" || ext === "m4a") args.push("-movflags", "+faststart");
    args.push(out);
    await run(process.env.FFMPEG_PATH || "ffmpeg", args, { timeout: 60_000 });
    return await readFile(out);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") {
      throw new HttpError("validation_error", "Audio and video uploads need ffmpeg installed on the server (set FFMPEG_PATH).");
    }
    throw new HttpError("validation_error", "The audio or video file could not be processed");
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

export type StoredMedia = { url: string; mediaType: MediaType; width: number | null; height: number | null };

export function uploadDir(): string {
  return path.resolve(process.env.UPLOAD_DIR ?? ".data/uploads");
}

const KEY_RE = /^[0-9a-f-]{36}\.(jpg|mp3|m4a|ogg|wav|mp4|webm)$/;
export const isValidKey = (key: string) => KEY_RE.test(key);

let s3: S3Client | undefined;
function s3Client(): S3Client {
  s3 ??= new S3Client({
    region: process.env.S3_REGION ?? "auto",
    endpoint: process.env.S3_ENDPOINT || undefined,
    credentials: { accessKeyId: process.env.S3_ACCESS_KEY_ID ?? "", secretAccessKey: process.env.S3_SECRET_ACCESS_KEY ?? "" },
  });
  return s3;
}

export async function storeUpload(file: File): Promise<StoredMedia> {
  if (file.size > MAX_UPLOAD_BYTES) throw new HttpError("payload_too_large", "File is too large");
  const input = Buffer.from(await file.arrayBuffer());
  const kind = sniff(input);
  if (!kind) throw new HttpError("validation_error", "Unsupported file type. Use JPEG, PNG, WebP, MP3, M4A, OGG, WAV, MP4 or WebM.");
  if (input.length > kind.maxBytes) throw new HttpError("payload_too_large", `${kind.mediaType} files can be at most ${kind.maxBytes / MB} MB`);

  let body: Buffer = input;
  let width: number | null = null;
  let height: number | null = null;
  if (kind.mediaType === "image") {
    try {
      const { data, info } = await sharp(input, { limitInputPixels: 50_000_000 })
        .rotate() // apply EXIF orientation before the metadata is dropped
        .resize({ width: IMAGE_WIDTH, height: IMAGE_HEIGHT, fit: "cover", position: "attention" })
        .jpeg({ quality: 85, mozjpeg: true })
        .toBuffer({ resolveWithObject: true });
      body = data;
      width = info.width;
      height = info.height;
    } catch {
      throw new HttpError("validation_error", "The image could not be read");
    }
  } else {
    body = await stripAvMetadata(input, kind.ext);
  }

  const key = `${randomUUID()}.${kind.ext}`;
  if (process.env.S3_BUCKET) {
    await s3Client().send(
      new PutObjectCommand({
        Bucket: process.env.S3_BUCKET,
        Key: key,
        Body: body,
        ContentType: kind.mime,
        CacheControl: "public, max-age=31536000, immutable",
      }),
    );
    const origin = process.env.MEDIA_PUBLIC_ORIGIN;
    if (!origin) throw new HttpError("internal", "MEDIA_PUBLIC_ORIGIN must be set when S3_BUCKET is used");
    return { url: `${origin.replace(/\/$/, "")}/${key}`, mediaType: kind.mediaType, width, height };
  }
  await mkdir(uploadDir(), { recursive: true });
  await writeFile(path.join(uploadDir(), key), body);
  return { url: `/api/media/${key}`, mediaType: kind.mediaType, width, height };
}

export async function readLocalMedia(key: string): Promise<{ body: Buffer; mime: string } | null> {
  if (!isValidKey(key)) return null;
  try {
    const body = await readFile(path.join(uploadDir(), key));
    return { body, mime: MIME_BY_EXT[key.split(".").pop()!] };
  } catch {
    return null;
  }
}

/** Media URLs the app accepts on items: bundled files, local uploads, or the configured bucket. */
export function isAllowedMediaUrl(url: string): boolean {
  if (/^\/media\/[A-Za-z0-9/_.-]+$/.test(url) && !url.includes("..")) return true;
  if (/^\/api\/media\//.test(url)) return isValidKey(url.slice("/api/media/".length));
  const origin = process.env.MEDIA_PUBLIC_ORIGIN?.replace(/\/$/, "");
  return Boolean(origin && url.startsWith(`${origin}/`) && isValidKey(url.slice(origin.length + 1)));
}
